import math

def limit_sepihak(f, c, side='both', h=1e-6):
    if side == 'left':
        return f(c - h)
    if side == 'right':
        return f(c + h)
    left = f(c - h)
    right = f(c + h)
    if abs(left - right) > 1e-3:
        return None
    return 0.5 * (left + right)

def is_kontinu_di(f, c, tol=1e-3):
    try:
        fc = f(c)
    except Exception:
        return False
    if fc is None or math.isnan(fc):
        return False
    lim = limit_sepihak(f, c, side='both')
    if lim is None:
        return False
    return abs(lim - fc) < tol

