def turunan_kedua(f, x, h=1e-4):
    return (f(x + h) - 2.0 * f(x) + f(x - h)) / (h ** 2)

def taylor_orde2(f, a, x):
    h1 = 1e-5
    f1 = (f(a + h1) - f(a - h1)) / (2.0 * h1)
    f2 = turunan_kedua(f, a)
    dx = x - a
    return f(a) + f1 * dx + 0.5 * f2 * (dx ** 2)

import math

def ekstrem_mutlak_kubik(a, b, c, d, x_min, x_max):
    f = lambda x: a * x**3 + b * x**2 + c * x + d
    kandidat = [x_min, x_max]
    # 3a x^2 + 2b x + c = 0
    A, B, C = 3 * a, 2 * b, c
    if abs(A) < 1e-12:
        if abs(B) > 1e-12:
            r = -C / B
            if x_min < r < x_max:
                kandidat.append(r)
    else:
        disc = B**2 - 4 * A * C
        if disc >= 0:
            sqrt_d = math.sqrt(disc)
            for r in [(-B - sqrt_d) / (2 * A), (-B + sqrt_d) / (2 * A)]:
                if x_min < r < x_max:
                    kandidat.append(r)
    nilai = [f(x) for x in kandidat]
    return (min(nilai), max(nilai))

