import numpy as np

def analisis_asimtot_rasional(p, q):
    p_arr = np.trim_zeros(np.array(p, dtype=float), 'f')
    q_arr = np.trim_zeros(np.array(q, dtype=float), 'f')
    deg_p = len(p_arr) - 1
    deg_q = len(q_arr) - 1
    if deg_p < deg_q:
        datar = 0.0
    elif deg_p == deg_q:
        datar = float(p_arr[0] / q_arr[0])
    else:
        datar = None
    roots = np.roots(q_arr)
    tegak = []
    for r in roots:
        if abs(r.imag) < 1e-8:
            rx = float(r.real)
            if abs(np.polyval(p_arr, rx)) > 1e-7:
                if not any(abs(rx - t) < 1e-6 for t in tegak):
                    tegak.append(rx)
    tegak.sort()
    return {'asimtot_datar': datar, 'asimtot_tegak': tegak}

def newton_raphson(f, df, x0, tol=1e-8, max_iter=50):
    x = float(x0)
    for _ in range(max_iter):
        fx = f(x)
        if abs(fx) < tol:
            return x
        dfx = df(x)
        if abs(dfx) < 1e-14:
            raise ZeroDivisionError('Turunan nol pada Newton-Raphson')
        x_next = x - fx / dfx
        if abs(x_next - x) < tol:
            return x_next
        x = x_next
    return x

def bisection(f, a, b, tol=1e-6, max_iter=100):
    fa, fb = f(a), f(b)
    if fa * fb > 0:
        raise ValueError('f(a) dan f(b) harus berlawanan tanda')
    if abs(fa) < tol:
        return float(a)
    if abs(fb) < tol:
        return float(b)
    for _ in range(max_iter):
        c = 0.5 * (a + b)
        fc = f(c)
        if abs(fc) < tol or 0.5 * (b - a) < tol:
            return c
        if fa * fc < 0:
            b, fb = c, fc
        else:
            a, fa = c, fc
    return 0.5 * (a + b)

