import math

def solusi_kuadrat_positif(a, b, c):
    disc = b ** 2 - 4 * a * c
    if abs(disc) < 1e-12:
        return ('kecuali_satu', -b / (2.0 * a))
    if disc < 0:
        return ('semua_real', None)
    sq = math.sqrt(disc)
    r1 = (-b - sq) / (2.0 * a)
    r2 = (-b + sq) / (2.0 * a)
    if r1 > r2:
        r1, r2 = r2, r1
    return ('dua_selang', (r1, r2))

def filter_rasional(p_fn, q_fn, xs):
    res = []
    for x in xs:
        qx = q_fn(x)
        if abs(qx) < 1e-12:
            continue
        if p_fn(x) / qx >= 0:
            res.append(x)
    return res

