import math

def cek_terdiferensialkan(f, c, h=1e-6, tol=1e-3):
    try:
        fc = f(c)
        d_left = (fc - f(c - h)) / h
        d_right = (f(c + h) - fc) / h
    except Exception:
        return False
    if math.isnan(d_left) or math.isnan(d_right) or abs(d_left) > 1e8 or abs(d_right) > 1e8:
        return False
    return abs(d_left - d_right) < tol

def turunan_implisit(F, x0, y0, h=1e-6):
    fx = (F(x0 + h, y0) - F(x0 - h, y0)) / (2.0 * h)
    fy = (F(x0, y0 + h) - F(x0, y0 - h)) / (2.0 * h)
    if abs(fy) < 1e-12:
        raise ZeroDivisionError('Turunan parsial terhadap y bernilai nol')
    return -fx / fy

def turunan_parametrik(x_fn, y_fn, t, h=1e-4):
    xp = (x_fn(t + h) - x_fn(t - h)) / (2.0 * h)
    yp = (y_fn(t + h) - y_fn(t - h)) / (2.0 * h)
    xpp = (x_fn(t + h) - 2.0 * x_fn(t) + x_fn(t - h)) / (h ** 2)
    ypp = (y_fn(t + h) - 2.0 * y_fn(t) + y_fn(t - h)) / (h ** 2)
    if abs(xp) < 1e-12:
        raise ZeroDivisionError('dx/dt bernilai nol')
    dy_dx = yp / xp
    d2y_dx2 = (xp * ypp - yp * xpp) / (xp ** 3)
    return (dy_dx, d2y_dx2)

