import math

def iterasi_min_bisection(a0, b0, eps):
    lebar = b0 - a0
    if lebar / 2.0 <= eps:
        return 0
    n = 0
    while lebar / (2 ** (n + 1)) > eps:
        n += 1
    return n

def batas_galat_bisection(a0, b0, n):
    return (b0 - a0) / (2 ** (n + 1))
